GSI_STRUCTURE=["Intact / Massive","Blocky","Very Blocky",
               "Blocky / Disturbed / Folded","Disintegrated","Laminated / Sheared"]
GSI_SURFACE=["Very Good  (fresh, rough, unweathered)",
             "Good  (slightly rough, slightly weathered)",
             "Fair  (smooth, moderately weathered)",
             "Poor  (slickensided, highly weathered)",
             "Very Poor  (slickensided, soft clay coatings)"]
GSI_MATRIX=[[75,68,57,47,38],[65,58,48,38,29],[57,50,41,33,25],
            [47,41,34,27,20],[36,31,26,20,14],[18,15,12,9,7]]
MI_VALUES={"Conglomerate":22,"Breccia":20,"Sandstone":17,"Siltstone":7,
           "Mudstone":4,"Shale":6,"Limestone":9,"Dolomite":9,"Chalk":7,"Coal":8,
           "Granite":33,"Granodiorite":30,"Diorite":28,"Gabbro":27,"Rhyolite":20,
           "Andesite":18,"Basalt":17,"Tuff":13,"Marble":9,"Hornfels":19,
           "Quartzite":24,"Metasandstone":19,"Phyllite":7,"Schist":12,
           "Gneiss":28,"Amphibolite":26}
def gsi_from_chart(si,sf): return GSI_MATRIX[si][sf]
def rmr89_to_gsi(rmr): return max(0,int(rmr)-5)
def hoek_brown_params(gsi,mi,D=0.0):
    mb=mi*math.exp((gsi-100)/(28-14*D))
    s=math.exp((gsi-100)/(9-3*D))
    a=0.5+(math.exp(-gsi/15)-math.exp(-20/3))/6
    return round(mb,4),round(s,6),round(a,4)
def rock_mass_ucs(sci,s,a): return round(sci*math.pow(s,a),2)
def rock_mass_tensile(sci,mb,s):
    if mb==0: return 0.0
    return round(-s*sci/mb,3)
def deformation_modulus(gsi,D,sci):
    return round(100000*(1-D/2)/(1+math.exp((75+25*D-gsi)/11))/1000,2)
def friction_angle_rm(gsi,mi,D,sci,sig3=0.001):
    mb,s,a=hoek_brown_params(gsi,mi,D)
    try:
        num=6*a*mb*math.pow(s+mb*sig3/sci,a-1)
        den=2*(1+a)*(2+a)+num
        return round(math.degrees(math.atan(num/den)),1)
    except: return 0.0
def cohesion_rm(sci,gsi,mi,D,sig3=0.001):
    mb,s,a=hoek_brown_params(gsi,mi,D)
    phi=math.radians(friction_angle_rm(gsi,mi,D,sci,sig3))
    try:
        sig1=sci*(mb*sig3/sci+s)**a
        c=(sig1-sig3*math.tan(phi+math.pi/4)**2)/(2*math.tan(phi+math.pi/4))
        return round(max(0.0,c),3)
    except: return 0.0
def classify_gsi(gsi):
    if gsi>=75: return "Very Good",C_GREEN
    if gsi>=55: return "Good",C_ACCENT
    if gsi>=35: return "Fair",C_TEAL
    if gsi>=20: return "Poor",C_AMBER
    return "Very Poor",C_RED

# ══════════════════════════════════════════════════════════════════
#  MATH — SMR
# ══════════════════════════════════════════════════════════════════
def romana_F1(diff):
    a=abs(diff)
    if a>30: return 0.15
    elif a>20: return 0.40
    elif a>10: return 0.70
    elif a>5:  return 0.85
    else:      return 1.00
def romana_F2_planar(b):
    if b<20: return 0.15
    elif b<30: return 0.40
    elif b<35: return 0.70
    elif b<45: return 0.85
    else: return 1.00
def romana_F3_planar(bj,bs):
    d=bj-bs
    if d>10: return 0
    elif d>0: return -6
    elif d>-10: return -25
    elif d>-20: return -50
    else: return -60
def romana_F3_topple(bj,bs):
    s=bj+bs
    if s<110: return 0
    elif s<120: return -6
    elif s<130: return -25
    elif s<140: return -50
    else: return -60
def tomas_F1(diff):
    a=abs(diff)
    return round((1-math.sin(math.radians(a)))**2,4)
def tomas_F2(b):
    return round(math.tan(math.radians(max(0.1,b)))**2,4)
def tomas_F3(bj,bs):
    d=bj-bs
    if d>=0: return 0
    return round(max(-60,-0.1165*d**2+0.0009*d**3-0.0000024*d**4),2)
def tomas_F3_topple(bj,bs):
    d=-(bj+bs-180)
    if d>=0: return 0
    return round(max(-60,-0.1165*d**2+0.0009*d**3-0.0000024*d**4),2)
SMR_F4={"Natural Slope":15,"Pre-splitting":10,"Smooth Blasting":8,
        "Normal Blasting / Mechanical":0,"Deficient Blasting":-8}
def compute_smr(rmr89,F1,F2,F3,F4):
    return round(max(0.0,min(100.0,rmr89+F1*F2*F3+F4)),1)
SMR_CLASSES=[
    (81,100,"I","Very Good",C_GREEN,"None","Completely stable","Isolated blocks","<0.1"),
    (61,80,"II","Good",C_ACCENT,"None / Scaling","Stable","Some blocks fall","0.1–0.4"),
    (41,60,"III","Normal",C_TEAL,"Systematic joints / local anchors","Partially stable","Planar failures in some joints","0.4–0.7"),
    (21,40,"IV","Bad",C_AMBER,"Important / corrective anchors","Unstable","Planar many joints / large wedge","0.7–0.9"),
    (0,20,"V","Very Bad",C_RED,"Re-excavation","Completely unstable","Large planar or soil circular","0.9–1.0"),
]
def classify_smr(smr):
    for lo,hi,cls,qual,col,support,stability,failure,prob in SMR_CLASSES:
        if lo<=smr<=hi: return cls,qual,col,support,stability,failure,prob
    return "V","Very Bad",C_RED,"Re-excavation","Completely unstable","Large planar","0.9–1.0"

