def classify_rhrs(total):
    if total < 300:
        return "Low Hazard",    C_GREEN, "Monitor periodically. Standard maintenance."
    elif total < 500:
        return "Moderate Hazard", C_AMBER, "Priority review. Consider mitigation measures."
    elif total < 700:
        return "High Hazard",   C_RED,   "Engineering mitigation required urgently."
    else:
        return "Very High Hazard", "#7f0000", "Immediate closure or remediation required."

