# ── BadgeWidget ───────────────────────────────────────────────────
class BadgeWidget:
    """Simple badge: CTkFrame border + CTkLabel inside.
    Supports .configure(text=..., text_color=...) directly."""
    def __init__(self, parent, row=0, col=0, width=68):
        self._frame = ctk.CTkFrame(parent, width=width+6, height=32,
                                   fg_color=C_BORDER, corner_radius=6)
        self._frame.grid(row=row, column=col, padx=6, pady=4)
        self._frame.grid_propagate(False)
        self._lbl = ctk.CTkLabel(self._frame, text="—",
                                  width=width, height=28,
                                  font=FONT_BADGE, text_color=C_TEAL,
                                  fg_color=C_CARD2)
        self._lbl.place(relx=0.5, rely=0.5, anchor="center")

    def configure(self, **kwargs):
        self._lbl.configure(**kwargs)

    def grid(self, **kwargs):
        self._frame.grid(**kwargs)

    def grid_remove(self):
        self._frame.grid_remove()


class App(ctk.CTk):
    def __init__(self):
        super().__init__()
        self.title(f"{APP_NAME}  ({APP_SHORT})")
        self.geometry("1480x960")
        self.minsize(1300,840)
        self.configure(fg_color=C_BG)
        self._rmr_result      = None
        self._gsi_result      = None
        self._smr_result      = None
        self._rhrs_result     = None
        self._scanline_result = None
        self._photos          = []   # list of {b64, note, lat, lon}
        self._load_images()
        self._build()

    def _load_images(self):
        self._banner = None
        self._icon   = None
        if not BANNER_B64 and not ICON_B64: return
        try:
            import base64 as _b64, io as _io
            from PIL import Image as _Img
            if BANNER_B64:
                _bi=_Img.open(_io.BytesIO(_b64.b64decode(BANNER_B64)))
                self._banner=ctk.CTkImage(_bi,size=(1440,180))
            if ICON_B64:
                _ii=_Img.open(_io.BytesIO(_b64.b64decode(ICON_B64)))
                self._icon=ctk.CTkImage(_ii,size=(52,52))
        except Exception:
            self._banner=None; self._icon=None

    # ── Layout ────────────────────────────────────────────────
    def _build(self):
        self.grid_columnconfigure(1,weight=1)
        self.grid_rowconfigure(0,weight=1)
        self._sidebar()

        main=ctk.CTkFrame(self,fg_color=C_BG,corner_radius=0)
        main.grid(row=0,column=1,sticky="nsew")
        main.grid_columnconfigure(0,weight=1)
        main.grid_rowconfigure(0,minsize=0)
        main.grid_rowconfigure(1,weight=1)

        if self._banner:
            # Banner with app name overlay
            bf = ctk.CTkFrame(main,fg_color="#0d1f3c",corner_radius=0)
            bf.grid(row=0,column=0,sticky="ew")
            ctk.CTkLabel(bf,image=self._banner,text="",
                         fg_color="#0d1f3c",corner_radius=0).pack(fill="x")
            # Title overlay on banner
            overlay=ctk.CTkFrame(bf,fg_color="transparent")
            overlay.place(relx=0,rely=0,relwidth=1,relheight=1)
            ctk.CTkLabel(overlay,
                text=f"{APP_NAME}  ({APP_SHORT})",
                font=("Georgia",17,"bold"),text_color="#ffffff",
                fg_color="transparent"
            ).place(x=14,y=8)
            ctk.CTkLabel(overlay,
                text=APP_SUBTITLE,
                font=("Courier New",12),text_color="#a8c5e8",
                fg_color="transparent"
            ).place(x=14,y=156)
        else:
            hdr=ctk.CTkFrame(main,fg_color="#0d1f3c",height=60,corner_radius=0)
            hdr.grid(row=0,column=0,sticky="ew")
            ctk.CTkLabel(hdr,text=f"{APP_NAME}  ({APP_SHORT})",
                         font=("Georgia",17,"bold"),text_color="#ffffff"
                         ).pack(side="left",padx=16,pady=10)

        self.tabs=ctk.CTkTabview(main,fg_color=C_PANEL,
            segmented_button_fg_color=C_CARD2,
            segmented_button_selected_color=C_ACCENT,
            segmented_button_unselected_color=C_CARD2,
            segmented_button_selected_hover_color=C_ACCENT,
            text_color=C_TEXT,corner_radius=0)
        self.tabs.grid(row=1,column=0,sticky="nsew")

        for t in ["  ① RMR  ","  ② GSI  ","  ③ SMR  ","  ④ RHRS  ","  ⑤ Scanline  ","  📷 Photos  ","  📊 Results  ","  🗺 Map  "]:
            self.tabs.add(t)

        self._tab_rmr(self.tabs.tab("  ① RMR  "))
        self._tab_gsi(self.tabs.tab("  ② GSI  "))
        self._tab_smr(self.tabs.tab("  ③ SMR  "))
        self._tab_rhrs(self.tabs.tab("  ④ RHRS  "))
        self._tab_scanline(self.tabs.tab("  ⑤ Scanline  "))
        self._tab_photos(self.tabs.tab("  📷 Photos  "))
        self._tab_results(self.tabs.tab("  📊 Results  "))
        self._tab_map(self.tabs.tab("  🗺 Map  "))

