    # ══════════════════════════════════════════════════════════════════
    #  CORE HELPERS
    # ══════════════════════════════════════════════════════════════════
    def _fval(self,entry,name,lo=0,hi=None,allow_neg=False):
        try: v=float(entry.get().strip())
        except ValueError: raise ValueError(f"'{name}' must be a number.")
        mn=lo if not allow_neg else -360
        if v<mn: raise ValueError(f"'{name}' must be ≥ {mn}.")
        if hi is not None and v>hi: raise ValueError(f"'{name}' must be ≤ {hi}.")
        return v

    def _set_badge(self,lbl,val):
        lbl.configure(text=f"{val:+.2f}" if val<0 else f"{val:.2f}")

    # ══════════════════════════════════════════════════════════════════
    #  CALCULATE
    # ══════════════════════════════════════════════════════════════════
    def _calculate(self):
        try:
            self._calc_rmr()
            self._calc_gsi()
            self._calc_smr()
            self._calc_rhrs()
            self._calc_scanline()
            self.tabs.set("  📊 Results  ")  # jump to results
        except ValueError as e:
            messagebox.showerror("Input Error",str(e))


