        ctk.CTkLabel(row1,text="Longitude:",font=FONT_LABEL,text_color=C_MUTED,width=90,anchor="w").pack(side="left",padx=(12,0))
        self.e_map_lon=ctk.CTkEntry(row1,width=160,fg_color=C_CARD2,border_color=C_BORDER,text_color=C_TEXT,font=FONT_ENTRY,placeholder_text="e.g. 125.5973")
